               return;
           }

           // Check for importantForAutofill on this element or parents
           if (hasImportantForAutofill(element)) {
               return;
           }

           context.report(ISSUE, element, context.getLocation(element),
               "Missing `autofillHints` attribute. Specify `autofillHints` or set `importantForAutofill` to exclude this view from autofill.");
       }

       private boolean hasImportantForAutofill(Element element) {
           Node current = element;
           while (current instanceof Element) {
               Element el = (Element) current;
               String important = el.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_IMPORTANT_FOR_AUTOFILL);
               if (important != null && !important.isEmpty()) {
                   return true;
               }
               current = el.getParentNode();
           }
           return false;
       }
   }
