        if (!isEditText && !hasInputType) {
            return;
        }

        String autofillHints = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_AUTOFILL_HINTS);
        if (autofillHints == null) {
            autofillHints = element.getAttribute("android:" + SdkConstants.ATTR_AUTOFILL_HINTS);
        }
        if (autofillHints != null && !autofillHints.isEmpty()) {
            return;
        }

        if (isExcludedFromAutofill(element)) {
            return;
        }

        context.report(ISSUE, element, context.getLocation(element),
            "Missing `autofillHints` attribute. Specify `autofillHints` or set `importantForAutofill` to exclude this view from autofill.");
    }

    private static boolean isExcludedFromAutofill(Element element) {
        String selfImportant = element.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_IMPORTANT_FOR_AUTOFILL);
        if (selfImportant == null) {
            selfImportant = element.getAttribute("android:" + SdkConstants.ATTR_IMPORTANT_FOR_AUTOFILL);
        }
        if ("no".equals(selfImportant) || "noExcludeDescendants".equals(selfImportant)) {
            return true;
        }

        Node current = element.getParentNode();
        while (current instanceof Element) {
            Element el = (Element) current;
            String parentImportant = el.getAttributeNS(SdkConstants.ANDROID_URI, SdkConstants.ATTR_IMPORTANT_FOR_AUTOFILL);
            if (parentImportant == null) {
                parentImportant = el.getAttribute("android:" + SdkConstants.ATTR_IMPORTANT_FOR_AUTOFILL);
            }
            if ("noExcludeDescendants".equals(parentImportant) || "yesExcludeDescendants".equals(parentImportant)) {
                return true;
            }
            current = el.getParentNode();
        }
        return false;
    }
}
